import { uuidv7 } from '@motivation/shared';
import type { ClientLogEntry, LogLevel, LogsResponse } from '@motivation/shared';
import { appendEntries, queryClientLogs, readDeviceIdentity, type DeviceIdentity } from './client-log-store.js';
import { extractModule } from '../../utils/component-logger.js';

// Realm-agnostic on purpose (story 382): the window, the DB worker and the SW
// all run this module, so it touches no window, document or localStorage. The
// window's identity is handed in by main.ts.

export interface ClientLogInput {
    level: LogLevel;
    module: string;
    message: string;
    context?: Record<string, unknown>;
}

const DEFAULT_FLUSH_MS = 250;
/** Story 382 (pwa-shell-05): a failing store is retried at doubling delays, up to this… */
const MAX_RETRY_MS = 60_000;
/** …holding at most this many entries meanwhile. The oldest go first. */
const MAX_BUFFERED = 1000;

/** An entry before the flush stamps its device identity on. */
type PendingEntry = Omit<ClientLogEntry, 'device_id' | 'device_label'>;

interface BatcherOptions {
    flushMs?: number;
    /** Hook fired after a successful flush — used to trigger background sync. */
    onFlush?: (count: number) => void;
    /**
     * The window's own identity, which it also records in the store. Without
     * one — the DB worker and the SW, which have no localStorage — the batcher
     * stamps the identity the window recorded.
     */
    identity?: () => DeviceIdentity;
    /** Where a failing store is reported: the realm's unpatched console, so the failure is not logged into the store that is failing. */
    report?: (...args: unknown[]) => void;
}

class ClientLogBatcher {
    private buffer: PendingEntry[] = [];
    private flushHandle: ReturnType<typeof setTimeout> | null = null;
    private readonly flushMs: number;
    private retryMs: number;
    private dropped = 0;
    private readonly onFlush: ((count: number) => void) | undefined;
    private readonly identity: (() => DeviceIdentity) | undefined;
    private readonly report: (...args: unknown[]) => void;

    constructor(options: BatcherOptions = {}) {
        this.flushMs = options.flushMs ?? DEFAULT_FLUSH_MS;
        this.retryMs = this.flushMs;
        this.onFlush = options.onFlush;
        this.identity = options.identity;
        this.report = options.report ?? console.warn.bind(console);
    }

    push(input: ClientLogInput): void {
        this.buffer.push(pendingEntry(input));
        this.cap();
        this.scheduleFlush();
    }

    private cap(): void {
        const excess = this.buffer.length - MAX_BUFFERED;
        if (excess <= 0) return;
        this.buffer.splice(0, excess);
        this.dropped += excess;
    }

    private scheduleFlush(): void {
        if (this.flushHandle != null) return;
        this.flushHandle = setTimeout(() => {
            this.flushHandle = null;
            // Story 382 (pwa-shell-05): never an unhandled rejection. The window
            // logs those as a new entry, which scheduled the next flush, which
            // failed again: a loop at the flush rate. backOff() reported it.
            this.flushNow().catch(() => undefined);
        }, this.retryMs);
    }

    async flushNow(): Promise<void> {
        if (this.flushHandle != null) {
            clearTimeout(this.flushHandle);
            this.flushHandle = null;
        }
        if (this.buffer.length === 0) return;
        const batch = this.buffer;
        const dropped = this.dropped;
        this.buffer = [];
        this.dropped = 0;
        const rows = dropped > 0
            ? [...batch, pendingEntry({
                level: 'warn',
                module: 'client-log',
                message: `${dropped} entries dropped while the client-log store was failing (it keeps the newest ${MAX_BUFFERED})`,
            })]
            : batch;
        try {
            const identity = this.identity?.() ?? await recordedIdentity();
            await appendEntries(rows.map((row) => ({ ...row, ...identity })), this.identity ? identity : undefined);
        } catch (error) {
            // Keep the entries for the retry: a later flush lands them, or
            // they go with the realm.
            this.buffer = [...batch, ...this.buffer];
            this.dropped += dropped;
            this.cap();
            this.backOff(error);
            throw error;
        }
        this.retryMs = this.flushMs;
        this.onFlush?.(rows.length);
    }

    /** Story 382 (pwa-shell-05): each failed write waits twice as long as the last, and a streak is reported once. */
    private backOff(error: unknown): void {
        if (this.retryMs === this.flushMs) {
            this.report(`client-log store write failed; retrying at doubling delays up to ${MAX_RETRY_MS} ms, keeping the newest ${MAX_BUFFERED} entries:`, error);
        }
        this.retryMs = Math.min(this.retryMs * 2, MAX_RETRY_MS);
        this.scheduleFlush();
    }

    /** Test-only: drop pending entries without flushing. */
    drainForTests(): PendingEntry[] {
        if (this.flushHandle != null) {
            clearTimeout(this.flushHandle);
            this.flushHandle = null;
        }
        const out = this.buffer;
        this.buffer = [];
        return out;
    }
}

function pendingEntry(input: ClientLogInput): PendingEntry {
    return {
        id: uuidv7(),
        // Story 385: the device's own zone offset survives the sync, so the line reads as its local time.
        timestamp: Temporal.Now.zonedDateTimeISO().toString({ timeZoneName: 'never' }),
        level: input.level,
        module: input.module,
        message: input.message,
        ...(input.context ? { context: input.context } : {}),
    };
}

async function recordedIdentity(): Promise<DeviceIdentity> {
    const identity = await readDeviceIdentity();
    if (!identity) {
        throw new Error('No device identity recorded yet: the window has not flushed a log since the client-log store was created');
    }
    return identity;
}

let singleton: ClientLogBatcher | null = null;
let installed = false;
let cleanupFns: Array<() => void> = [];

function getBatcher(options?: BatcherOptions): ClientLogBatcher {
    if (!singleton) singleton = new ClientLogBatcher(options);
    return singleton;
}

/** Filtered query used by the `<log-viewer>` source on the Debug screen. */
export function queryRecentClientLogs(filters: { level?: LogLevel[]; search?: string }): Promise<LogsResponse> {
    return queryClientLogs(filters);
}

/** Force-flush the pending batch (used on `pagehide`). Returns the number flushed. */
export async function flushClientLogBatch(): Promise<void> {
    if (singleton) await singleton.flushNow();
}

/**
 * Push a single entry into the client-log batcher. Used by the Debug screen
 * to leave visible markers (e.g. after a "Clear buffer" press).
 */
export function pushClientLogEntry(input: ClientLogInput): void {
    getBatcher().push(input);
}

function defaultOnFlush(): void {
    // Fire-and-forget: a registration failure (no SW yet, no Background Sync,
    // the permission denied) is surfaced by the Debug screen's shipping status.
    // Logging it here would feed this batcher a new entry on every flush.
    void import('./client-log-shipping.js').then(m => m.requestClientLogSync()).catch(() => undefined);
}

/**
 * The realm a capture runs in (story 382). Every realm writes the one store
 * the SW ships from. The window knows its device, records it, asks for the
 * sync and flushes on pagehide. The DB worker and the SW file untagged calls
 * under their own name and stamp the identity the window recorded. They ask
 * for no sync: one the SW asked for while shipping would log, flush and ask
 * again. Their entries go with the window's next sync.
 */
type CaptureRealm =
    | { realm: 'window'; identity: () => DeviceIdentity; onFlush?: (count: number) => void; batcher?: ClientLogBatcher }
    | { realm: 'worker' | 'sw' };

export type InstallOptions = CaptureRealm & { flushMs?: number };

const CONSOLE_METHODS: Array<{ name: 'log' | 'info' | 'warn' | 'error' | 'debug'; level: LogLevel }> = [
    { name: 'log',   level: 'info' },
    { name: 'info',  level: 'info' },
    { name: 'warn',  level: 'warn' },
    { name: 'error', level: 'error' },
    { name: 'debug', level: 'debug' },
];

export function installConsoleCapture(options: InstallOptions): ClientLogBatcher {
    const onWindow = options.realm === 'window';
    const batcher = (onWindow ? options.batcher : undefined) ?? getBatcher({
        flushMs: options.flushMs,
        onFlush: onWindow ? options.onFlush ?? defaultOnFlush : undefined,
        identity: onWindow ? options.identity : undefined,
        report: console.warn.bind(console),
    });
    if (onWindow && options.batcher) singleton = options.batcher;

    if (installed) return batcher;
    installed = true;

    const untaggedModule = onWindow ? 'client' : options.realm;
    for (const { name, level } of CONSOLE_METHODS) {
        const original = console[name].bind(console);
        const patched = (...args: unknown[]) => {
            const { module, cleanArgs } = extractModule(args, untaggedModule);
            try {
                batcher.push(buildEntryFromArgs(level, module, cleanArgs));
            } catch {
                // Never let the logger crash the app.
            }
            // extractModule hands back `args` itself when there was no tag.
            original(...(cleanArgs === args ? args : withModulePrefix(module, cleanArgs)));
        };
        console[name] = patched as typeof console[typeof name];
        cleanupFns.push(() => { console[name] = original as typeof console[typeof name]; });
    }

    const errorModule = onWindow ? 'window' : options.realm;
    const onError = (event: ErrorEvent) => {
        const err = event.error;
        const message = event.message || (err instanceof Error ? err.message : String(err));
        const context: Record<string, unknown> = {};
        if (event.filename) context.filename = event.filename;
        if (typeof event.lineno === 'number') context.lineno = event.lineno;
        if (typeof event.colno === 'number') context.colno = event.colno;
        if (err instanceof Error && err.stack) context.stack = err.stack;
        batcher.push({ level: 'error', module: errorModule, message, context: Object.keys(context).length ? context : undefined });
    };
    const onRejection = (event: Event) => {
        const reason = (event as unknown as { reason?: unknown }).reason;
        const message = reason instanceof Error ? reason.message : safeStringify(reason);
        const context: Record<string, unknown> = {};
        if (reason instanceof Error && reason.stack) context.stack = reason.stack;
        batcher.push({
            level: 'error',
            module: errorModule,
            message: `Unhandled promise rejection: ${message}`,
            context: Object.keys(context).length ? context : undefined,
        });
    };

    globalThis.addEventListener('error', onError as EventListener);
    globalThis.addEventListener('unhandledrejection', onRejection as EventListener);
    cleanupFns.push(() => {
        globalThis.removeEventListener('error', onError as EventListener);
        globalThis.removeEventListener('unhandledrejection', onRejection as EventListener);
    });

    if (onWindow) {
        const onPageHide = () => {
            // pagehide fires sync; the IDB transaction is async but starts before
            // the lifecycle event resolves, which is good enough for a dev tool.
            // A failure was reported by the batcher's backoff.
            batcher.flushNow().catch(() => undefined);
        };
        globalThis.addEventListener('pagehide', onPageHide);
        cleanupFns.push(() => globalThis.removeEventListener('pagehide', onPageHide));
    }

    return batcher;
}

/** Test-only: undo console patching and reset the singleton. */
export function resetClientLogCaptureForTests(): void {
    for (const fn of cleanupFns) fn();
    cleanupFns = [];
    installed = false;
    singleton = null;
}

/**
 * The realm's console keeps a component logger's tag as a `[module]` prefix
 * (story 382), so devtools still says who spoke once `[SYNC-DEBUG][x]`
 * prefixes became tags. Joined into a string first argument, so a format
 * string stays first.
 */
function withModulePrefix(module: string, args: unknown[]): unknown[] {
    const [first, ...rest] = args;
    return typeof first === 'string' ? [`[${module}] ${first}`, ...rest] : [`[${module}]`, ...args];
}

function buildEntryFromArgs(level: LogLevel, module: string, args: unknown[]): ClientLogInput {
    if (args.length === 0) return { level, module, message: '' };
    const [first, ...rest] = args;
    const message = typeof first === 'string' ? first : safeStringify(first);
    if (rest.length === 0) return { level, module, message };
    return {
        level,
        module,
        message,
        context: { args: rest.map(safeClone) },
    };
}

function safeStringify(value: unknown): string {
    try {
        if (typeof value === 'string') return value;
        return JSON.stringify(value, circularReplacer()) ?? String(value);
    } catch {
        return String(value);
    }
}

function safeClone(value: unknown): unknown {
    try {
        return JSON.parse(JSON.stringify(value, circularReplacer()));
    } catch {
        return String(value);
    }
}

function circularReplacer(): (key: string, value: unknown) => unknown {
    const seen = new WeakSet<object>();
    return (_key, value) => {
        if (value instanceof Error) {
            return { name: value.name, message: value.message, stack: value.stack };
        }
        if (typeof value === 'object' && value !== null) {
            if (seen.has(value)) return '[Circular]';
            seen.add(value);
        }
        return value;
    };
}

export { ClientLogBatcher };
